INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$ps-store-dan-oyin-sotib-olish$x$,
  $x$Oʻzbekistondan PS Store’da oʻyin qanday sotib olinadi$x$,
  $x$PSN akkaunti uchun qaysi davlatni tanlash, nega uni oʻzgartirib boʻlmaydi, qaysi PS Store kartasi mos keladi va uni PS5 hamda saytda qanday faollashtirish.$x$,
$x$<p>Oʻzbekistondan PS Store’da oʻyin sotib olish uchun maʼlum bir davlatning PSN akkaunti va aynan shu davlatning PS Store sovgʻa kartasi kerak. Karta akkaunt hamyonini toʻldiradi, hamyondan esa oʻyinlar va PS Plus toʻlanadi.</p>
<h2>Asosiysi</h2>
<ul>
<li>PSN akkaunti davlati roʻyxatdan oʻtishda bir marta tanlanadi. Keyin uni oʻzgartirib boʻlmaydi.</li>
<li>PS Store kartasi faqat shu davlat akkauntida ishlaydi. Turk kartasi — turk akkaunti uchun, Amerika kartasi — Amerika akkaunti uchun.</li>
<li>Hamyondagi pul akkaunt davlati valyutasida saqlanadi va boshqa regionga oʻtmaydi.</li>
<li>Boshqa davlat doʻkoni kerak boʻlsa, ikkinchi akkaunt ochiladi va PS5’da foydalanuvchilar almashtiriladi.</li>
<li>YuPay’da 43 davlatning PSN kartalari bitta sahifada. Toʻlov soʻmda, Click, Payme yoki Uzum orqali: soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan u yechiladi.</li>
</ul>
<h2>Akkaunt uchun qaysi davlatni tanlash</h2>
<p>Oʻzbekistondagi oʻyinchilar odatda boshqa davlat akkauntidan foydalanadi: Turkiya, BAA, AQSh, Polsha va boshqalar.</p>
<p>Davlat uch narsani belgilaydi:</p>
<ul>
<li><strong>valyuta va narxlar</strong> — turk doʻkonida narxlar lirada, Amerika doʻkonida dollarda;</li>
<li><strong>katalog va til</strong> — oʻyinlar roʻyxati va lokalizatsiya regionga qarab farq qiladi;</li>
<li><strong>qaysi kartalar mos keladi</strong> — faqat shu davlat kartalari.</li>
</ul>
<p>Turk PS Store narxlari tufayli mashhur. Lekin Sony ularni bir necha marta oshirgan: faqat PS Plus 2025-yilda 55 % qimmatlashdi. Kerakli oʻyin narxini turli regionlarda oʻzingiz solishtiring — roʻyxatdan oʻtishdan oldin, keyin emas.</p>
<p>Agar xaridlar va kuboklar bor akkauntingiz boʻlsa, odatda unda qolish osonroq. Uning davlatini konsoldagi yoki PlayStation saytidagi akkaunt sozlamalarida koʻrish mumkin.</p>
<h2>Nega davlatni oʻzgartirib boʻlmaydi</h2>
<p>Sony buni ochiq yozadi: akkaunt yaratilgandan keyin uning davlati yoki regionini oʻzgartirib boʻlmaydi. Hamyon ham shunday: pul akkaunt valyutasida qoladi, boshqa region mablagʻidan foydalanib boʻlmaydi.</p>
<p>Amaliy xulosa oddiy. Davlatni xato tanlasangiz, yangi akkaunt ochishga toʻgʻri keladi. Eski akkauntda olingan oʻyinlar va obuna oʻsha yerda qoladi.</p>
<h2>Ikkinchi akkaunt va foydalanuvchini almashtirish</h2>
<p>Koʻpchilik ikkita akkaunt yuritadi: asosiysi va, masalan, mahalliy narxlarda xarid qilish uchun turk akkaunti. Yangi akkaunt uchun alohida pochta kerak boʻladi.</p>
<p>PS5’da ular orasida almashish oson:</p>
<ol>
<li>Geympaddagi PS tugmasini bosing.</li>
<li>Boshqaruv markazini oching.</li>
<li>Foydalanuvchini almashtirishni tanlang va ikkinchi akkauntga kiring.</li>
</ol>
<p>Kartani davlati unga mos keladigan akkauntda faollashtiring. Har bir akkauntning hamyoni alohida.</p>
<h2>PSN kartasini PS5’da qanday faollashtirish</h2>
<ol>
<li>Kerakli davlat akkauntiga kiring.</li>
<li>PlayStation Store’ni oching.</li>
<li>Doʻkonning yuqori qismidagi «…» tugmasini bosing va kodni faollashtirishni tanlang.</li>
<li>Kartadagi kodni kiriting va tasdiqlang.</li>
</ol>
<p>Summa akkaunt hamyoniga tushadi. Shundan soʻng oʻyin yoki PS Plus’ni odatdagidek toʻlash mumkin.</p>
<p>Kod qabul qilinmayaptimi? Avval qaysi akkauntga kirganingizni va uning davlati karta davlati bilan mos kelishini tekshiring. Soʻng kodning oʻzini solishtiring: ortiqcha boʻsh joy yoki adashtirilgan harf ham xuddi shu xatoni beradi.</p>
<h2>Kartani saytda qanday faollashtirish</h2>
<ol>
<li>store.playstation.com’ni oching va oʻsha akkauntga kiring.</li>
<li>Avatarni bosing va kodlarni faollashtirishni tanlang.</li>
<li>Kodni kiriting va tasdiqlang.</li>
</ol>
<p>Bu konsolni yoqmasdan hamyonni oldindan toʻldirish uchun qulay.</p>
<h2>Xariddan oldin nimani tekshirish kerak</h2>
<ul>
<li><strong>Akkaunt davlati.</strong> Uni karta olishdan oldin sozlamalarda koʻring, xotiraga tayanmang.</li>
<li><strong>Karta davlati.</strong> Akkaunt davlati bilan bir xil boʻlishi kerak.</li>
<li><strong>Nominal.</strong> Mahalliy valyutadagi narxni hisobga olganda oʻyinga yetadimi? Yetmasa, ikkita karta yoki kattaroq karta oling.</li>
<li><strong>PS Plus.</strong> Obuna u boʻladigan akkaunt hamyonidan toʻlanadi. Demak, karta ham shu akkaunt davlatiniki boʻlishi kerak.</li>
<li><strong>Oʻyin regioni.</strong> Baʼzi oʻyinlar regionga bogʻlangan. Masalan, <a href="/uz/blog/gta-6-ni-ozbekistonda-sotib-olish">PS5 uchun GTA 6 kodlari</a> faqat mos region akkauntida ishlaydi. Xavfsiz yoʻl — oʻyinni oʻz akkauntingiz doʻkonidan olish.</li>
</ul>
<h2>Koʻp uchraydigan xatolar</h2>
<ul>
<li><strong>Boshqa davlat kartasi.</strong> Eng koʻp uchraydigani. Turk akkaunti Amerika kartasini qabul qilmaydi va aksincha. Kod buzilmaydi, lekin bu akkauntga tushmaydi.</li>
<li><strong>Akkaunt davlatini oʻzgartirishga urinish.</strong> Bu mumkin emas. Yagona yoʻl — ikkinchi akkaunt.</li>
<li><strong>Karta boshqa foydalanuvchida faollashtirilgan.</strong> Ikkita akkauntli konsolda hozir kim kirganini tekshiring.</li>
<li><strong>Pul «koʻchib oʻtadi» deb kutish.</strong> Bir region mablagʻi boshqasida ishlamaydi.</li>
</ul>
<h2>YuPay’da PSN kartasini qanday sotib olish</h2>
<ol>
<li>YuPay katalogida <a href="/uz/store/playstation">PlayStation Store</a> sahifasini oching.</li>
<li>Akkauntingiz davlatini tanlang, masalan <a href="/uz/store/playstation?region=tr">Turkiya</a> yoki <a href="/uz/store/playstation?region=us">AQSh</a>.</li>
<li>Nominalni tanlang.</li>
<li>Click, Payme yoki Uzum orqali soʻmda toʻlang.</li>
<li>Kod buyurtma sahifasiga va e-mail’ga keladi.</li>
</ol>
<p>Xbox’da ham oʻynaysizmi? U yerda qoidalar boshqacha: Microsoft akkaunti davlatini oʻzgartirish mumkin, lekin cheklovlar bilan. Batafsil — <a href="/uz/blog/xbox-hisobini-toldirish">Xbox hisobini Oʻzbekistondan toʻldirish</a> qoʻllanmasida.</p>
<p>Akkauntingiz davlatini bilasizmi? <a href="/uz/store/playstation">PlayStation Store kartalari</a> sahifasini oching, shu davlatni va kerakli oʻyinga yetadigan nominalni tanlang.</p>$x$,
  $x$Oʻzbekistonda PS Store’dan oʻyin sotib olish — PSN kartalari$x$,
  $x$Oʻzbekistondan PS Store’da oʻyin va PS Plus sotib olish: akkaunt davlati, kerakli davlatning PSN kartasi (Turkiya, AQSh, BAA), PS5’da faollashtirish va xatolar.$x$
);

